                        string chunkName = $"Chunk {threadCount}";

                        Thread thread = new Thread(() => {
                            //等待信号量槽位可用                         
                            semaphore.WaitOne();
                            try{
                                invokeDataProcessor(chunkName, chunkCopy);
                            }
                            catch(Exception ex)
                            {
                                Console.WriteLine(ex.Message);
                            }
                            finally{
                                semaphore.Release();
                            }
                            
                        });

                        threads.Add(thread);

